def btn(label, kind='gold', link=None, product='', arrow=True):
  cls={'gold':'btn btn-gold','dark':'btn btn-dark','outline':'btn btn-outline','light':'btn btn-outline-light'}[kind]
  if link:
    return f'<a class="{cls}" href="{link}">{label} <span class="arrow" aria-hidden="true">↗</span></a>'
  return f'<button class="{cls}" type="button" data-quote="{escape(product,quote=True)}">{label} <span class="arrow" aria-hidden="true">↗</span></button>'
def link(label,url): return f'<a class="text-link" href="{url}">{label} <span class="arrow" aria-hidden="true">↗</span></a>'
def eyebrow(label, color='dark'):return f'<span class="eyebrow {color}">{label}</span>'
def reveal(data,delay=''):return f'<div class="reveal {delay}">{data}</div>'
