def wrap(content,title,description,active='home',home=False):
 return f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0c282c"><meta name="description" content="{escape(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:site_name" content="Prime Reach Exports"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:image" content="{PHOTO['cargo']}"><meta name="twitter:card" content="summary_large_image"><title>{escape(title)}</title><link rel="icon" href="assets/img/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="preconnect" href="https://images.unsplash.com"><link rel="stylesheet" href="assets/css/style.css"><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@type':'Organization','name':'Prime Reach Exports','description':'Indian-origin salt and Rajasthan flour mill emery stone sourcing and international trade','areaServed':'Worldwide','address':{'@type':'PostalAddress','addressCountry':'IN'},'telephone':'+91-9694681337'},separators=(',',':'))}</script><script src="assets/js/site.js" defer></script></head><body><a class="skip-link" href="#main">Skip to content</a>{nav(active,home)}<main id="main">{content}</main>{footer()}{utility()}</body></html>'''
def write(name,content,title,description,active='home',home=False): (P/name).write_text(wrap(content,title,description,active,home),encoding='utf-8')

